import http from 'http';
import { FSWatcher } from 'chokidar';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  template?: string;
  layout?: string | false;
  [key: string]: unknown;
}

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  sourcePath: string;
  frontmatter: Frontmatter;
  template?: string;
  layout?: string | false;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
}

export interface Site {
  pages: Page[];
  outputDir: string;
}

export interface ServeOptions {
  contentDir?: string;
  outputDir?: string;
  templatesDir?: string;
  port?: number;
  host?: string;
  debounce?: number;
}

export interface DevServer {
  server: http.Server;
  port: number;
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  watcher: FSWatcher;
  close(): Promise<void>;
}

import { BuildOptions, Page } from './types';

export type HookResult = void | Promise<void>;

export type LifecycleHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

export interface Plugin {
  name: string;
  onStart?(): HookResult;
  beforeBuild?(): HookResult;
  afterBuild?(): HookResult;
  onFile?(page: Page): HookResult;
  onEnd?(): HookResult;
}

export interface PluginContext {
  options: BuildOptions;
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  pages: Page[];
}

/**
 * Runs each lifecycle hook across all plugins in registration order.
 */
export class PluginPipeline {
  constructor(readonly plugins: Plugin[]) {}

  runSync(hook: LifecycleHook): void {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (fn) {
        void fn.call(plugin);
      }
    }
  }

  runFileSync(page: Page): void {
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        void plugin.onFile(page);
      }
    }
  }

  async run(hook: LifecycleHook): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (fn) {
        await fn.call(plugin);
      }
    }
  }

  async runFile(page: Page): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        await plugin.onFile(page);
      }
    }
  }
}

import matter from 'gray-matter';
import { marked } from 'marked';
import { Frontmatter } from './types';

// Matches a YAML frontmatter block. The opening `---` may be preceded only by
// optional leading whitespace so that marked never sees the delimiters.
const FRONTMATTER_REGEX = /^\s*---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/;

/**
 * Split raw markdown into frontmatter data and the markdown body.
 *
 * The frontmatter block is stripped manually with a regex before the body is
 * handed to `marked`, otherwise `marked` renders the `---` delimiters as a
 * literal horizontal rule. gray-matter is used only to parse the YAML data.
 */
export function splitFrontmatter(raw: string): { data: Frontmatter; body: string } {
  const match = raw.match(FRONTMATTER_REGEX);
  if (!match) {
    return { data: {}, body: raw };
  }

  let data: Frontmatter = {};
  try {
    // gray-matter requires the opening `---` to be the very first bytes of its
    // input, so rebuild a clean block (leading whitespace already stripped).
    data = (matter(`---\n${match[1]}\n---`).data as Frontmatter) ?? {};
  } catch {
    data = {};
  }

  const body = raw.slice(match[0].length);
  return { data, body };
}

export function normalizeDate(value: unknown): string | undefined {
  if (value == null) return undefined;
  if (value instanceof Date) {
    return value.toISOString().slice(0, 10);
  }
  const str = String(value).trim();
  return str.length > 0 ? str : undefined;
}

/**
 * Parse raw markdown (with optional frontmatter) into frontmatter data and
 * rendered HTML. The returned HTML is a document fragment (no <html>/<body>).
 */
export function parseMarkdown(raw: string): { frontmatter: Frontmatter; html: string } {
  const { data, body } = splitFrontmatter(raw);
  const html = marked.parse(body, { async: false }) as string;
  return {
    frontmatter: { ...data, date: normalizeDate(data.date) },
    html,
  };
}

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((t) => String(t));
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
  }
  return [];
}

export function defaultTitle(slug: string): string {
  return slug
    .split(/[/\\-]/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

import fs from 'fs';
import path from 'path';

export interface SsgConfig {
  plugins?: string[];
}

const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js'];

/**
 * Load the project configuration from ssg.config.ts (or a compiled
 * ssg.config.js fallback). A raw TypeScript config can only be required when a
 * runtime loader (ts-node/tsx) is active, so unloadable files are skipped.
 */
export function loadConfig(cwd: string): SsgConfig {
  for (const filename of CONFIG_FILENAMES) {
    const file = path.join(cwd, filename);
    if (!fs.existsSync(file)) {
      continue;
    }
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const loaded = require(file);
      return normalizeConfig(loaded && 'default' in loaded ? loaded.default : loaded);
    } catch {
      // Ignore configs that cannot be loaded at runtime.
    }
  }
  return {};
}

function normalizeConfig(raw: unknown): SsgConfig {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    const plugins = (raw as { plugins?: unknown }).plugins;
    if (Array.isArray(plugins)) {
      return { plugins: plugins.filter((p): p is string => typeof p === 'string') };
    }
  }
  return {};
}

import fs from 'fs';
import { Plugin } from '../plugin';
import { Page } from '../types';
import { parseMarkdown, normalizeTags, defaultTitle } from '../markdown';

/**
 * Built-in plugin that parses raw markdown (with optional frontmatter) into
 * the page's HTML and metadata. Registered on the `onFile` hook so it runs for
 * every discovered markdown file.
 */
export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  onFile(page: Page): void {
    const raw = fs.readFileSync(page.sourcePath, 'utf8');
    const { frontmatter, html } = parseMarkdown(raw);

    page.html = html;
    page.frontmatter = frontmatter;
    page.title = frontmatter.title ?? defaultTitle(page.slug);
    page.date = frontmatter.date != null ? String(frontmatter.date) : undefined;
    page.tags = normalizeTags(frontmatter.tags);
    page.template = typeof frontmatter.template === 'string' ? frontmatter.template : undefined;
    page.layout = frontmatter.layout;
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext } from '../plugin';
import { Page } from '../types';
import {
  TemplateEngine,
  DEFAULT_TEMPLATE_NAME,
  DEFAULT_LAYOUT_NAME,
} from '../templates';

function pageSummary(page: Page): Record<string, unknown> {
  return {
    slug: page.slug,
    title: page.title,
    date: page.date,
    tags: page.tags,
    url: `${page.slug}.html`,
  };
}

function buildPageContext(page: Page, pages: Page[]): Record<string, unknown> {
  return {
    ...page.frontmatter,
    title: page.title,
    date: page.date,
    tags: page.tags,
    slug: page.slug,
    content: page.html,
    body: page.html,
    site: {
      pages: pages.map(pageSummary),
    },
  };
}

/**
 * Built-in plugin that renders each page through the template engine and writes
 * the resulting HTML to the output directory. Rendering happens on the
 * `afterBuild` hook so every page (and its metadata) is available for the
 * `site.pages` context used by templates and partials.
 */
export class TemplatePlugin implements Plugin {
  name = 'template';

  private readonly engine: TemplateEngine;

  constructor(private readonly context: PluginContext) {
    this.engine = new TemplateEngine(context.templatesDir, {
      defaultTemplate: context.options.defaultTemplate ?? DEFAULT_TEMPLATE_NAME,
      defaultLayout: context.options.defaultLayout ?? DEFAULT_LAYOUT_NAME,
    });
  }

  afterBuild(): void {
    const { pages, outputDir } = this.context;
    for (const page of pages) {
      const rendered = this.engine.render(page.template, page.layout, buildPageContext(page, pages));
      const outFile = path.join(outputDir, `${page.slug}.html`);
      fs.mkdirSync(path.dirname(outFile), { recursive: true });
      fs.writeFileSync(outFile, rendered);
    }
  }
}

import fs from 'fs';
import http from 'http';
import path from 'path';
import { watch, FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { Plugin } from '../plugin';
import { BuildOptions, DevServer, ServeOptions, Site } from '../types';

export const RELOAD_MESSAGE = 'reload';

export const LIVE_RELOAD_SCRIPT = `<script>
(function () {
  var socket = new WebSocket('ws://' + window.location.host);
  socket.addEventListener('message', function (event) {
    if (event.data === '${RELOAD_MESSAGE}') {
      window.location.reload();
    }
  });
})();
</script>`;

const CONTENT_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
};

export function injectLiveReloadScript(
  html: string,
  script: string = LIVE_RELOAD_SCRIPT
): string {
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, script + '\n</body>');
  }
  return html + '\n' + script;
}

function isHtml(filePath: string): boolean {
  const ext = path.extname(filePath).toLowerCase();
  return ext === '.html' || ext === '.htm';
}

function contentTypeFor(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return CONTENT_TYPES[ext] ?? 'application/octet-stream';
}

function createRequestHandler(outputDir: string): http.RequestListener {
  return (req, res) => {
    const rawPath = (req.url ?? '/').split('?')[0];
    let pathname: string;
    try {
      pathname = decodeURIComponent(rawPath);
    } catch {
      res.writeHead(400);
      res.end('Bad request');
      return;
    }

    const relative = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
    const filePath = path.resolve(outputDir, relative);

    if (filePath !== outputDir && !filePath.startsWith(outputDir + path.sep)) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    let body = fs.readFileSync(filePath);
    if (isHtml(filePath)) {
      body = Buffer.from(injectLiveReloadScript(body.toString('utf8')));
    }

    res.writeHead(200, { 'Content-Type': contentTypeFor(filePath) });
    res.end(body);
  };
}

/**
 * Built-in plugin that owns the live-reload development server: it performs an
 * initial build, serves the generated site over HTTP, injects the WebSocket
 * client script into HTML responses, watches the content and templates
 * directories for changes, rebuilds on change, and tells connected browsers to
 * reload when a rebuild completes.
 */
export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private server?: http.Server;
  private wss?: WebSocketServer;
  private watcher?: FSWatcher;
  private timer: NodeJS.Timeout | null = null;
  private building = false;
  private pending = false;

  private readonly contentDir: string;
  private readonly outputDir: string;
  private readonly templatesDir: string;
  private readonly host: string;
  private readonly port: number;
  private readonly debounce: number;

  constructor(
    private readonly build: (options: BuildOptions) => Site,
    options: ServeOptions = {}
  ) {
    this.contentDir = path.resolve(options.contentDir ?? 'content');
    this.outputDir = path.resolve(options.outputDir ?? 'dist');
    this.templatesDir = path.resolve(options.templatesDir ?? 'templates');
    this.host = options.host ?? '127.0.0.1';
    this.port = options.port ?? 3000;
    this.debounce = options.debounce ?? 100;
  }

  onStart(): void {
    // The initial build and server setup are performed by start().
  }

  async onEnd(): Promise<void> {
    await this.close();
  }

  async start(): Promise<DevServer> {
    await this.onStart();

    this.build({
      contentDir: this.contentDir,
      outputDir: this.outputDir,
      templatesDir: this.templatesDir,
    });

    const server = http.createServer(createRequestHandler(this.outputDir));
    const wss = new WebSocketServer({ server });

    const watcher = watch([this.contentDir, this.templatesDir], { ignoreInitial: true });
    const watcherReady = new Promise<void>((resolve) => {
      watcher.once('ready', () => resolve());
    });

    watcher.on('all', () => this.scheduleRebuild());

    await new Promise<void>((resolve, reject) => {
      server.once('error', reject);
      server.listen(this.port, this.host, () => resolve());
    });

    await watcherReady;

    this.server = server;
    this.wss = wss;
    this.watcher = watcher;

    const address = server.address();
    const actualPort = typeof address === 'object' && address !== null ? address.port : this.port;

    return {
      server,
      port: actualPort,
      contentDir: this.contentDir,
      outputDir: this.outputDir,
      templatesDir: this.templatesDir,
      watcher,
      close: () => this.close(),
    };
  }

  async close(): Promise<void> {
    const { server, wss, watcher } = this;
    return new Promise<void>((resolve) => {
      if (this.timer) {
        clearTimeout(this.timer);
        this.timer = null;
      }
      if (wss) {
        for (const client of wss.clients) {
          client.terminate();
        }
      }
      const finish = (): void => {
        if (wss) {
          wss.close(() => {
            if (server) {
              server.close(() => resolve());
            } else {
              resolve();
            }
          });
        } else if (server) {
          server.close(() => resolve());
        } else {
          resolve();
        }
      };
      if (watcher) {
        watcher.close().then(finish);
      } else {
        finish();
      }
    });
  }

  private rebuild(): void {
    if (this.building) {
      this.pending = true;
      return;
    }
    this.building = true;
    this.pending = false;
    try {
      this.build({
        contentDir: this.contentDir,
        outputDir: this.outputDir,
        templatesDir: this.templatesDir,
      });
      this.broadcast(RELOAD_MESSAGE);
    } catch (err) {
      console.error('Rebuild failed:', err);
    } finally {
      this.building = false;
      if (this.pending) {
        this.pending = false;
        this.scheduleRebuild();
      }
    }
  }

  private scheduleRebuild(): void {
    if (this.timer) {
      clearTimeout(this.timer);
    }
    this.timer = setTimeout(() => {
      this.timer = null;
      this.rebuild();
    }, this.debounce);
  }

  private broadcast(message: string): void {
    if (!this.wss) {
      return;
    }
    for (const client of this.wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  }
}

export { MarkdownPlugin } from './markdown-plugin';
export { TemplatePlugin } from './template-plugin';
export { DevServerPlugin } from './dev-server-plugin';

import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext, PluginPipeline } from './plugin';
import { BuildOptions, Page, Site } from './types';
import { escapeHtml } from './markdown';
import { loadConfig } from './config';
import { MarkdownPlugin } from './plugins/markdown-plugin';
import { TemplatePlugin } from './plugins/template-plugin';

export const DEFAULT_CONTENT_DIR = 'content';
export const DEFAULT_OUTPUT_DIR = 'dist';
export const DEFAULT_TEMPLATES_DIR = 'templates';

function listMarkdownFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    return [];
  }
  const results: string[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...listMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(full);
    }
  }
  return results;
}

function deriveSlug(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath);
  const parsed = path.parse(relative);
  return path.join(parsed.dir, parsed.name).split(path.sep).join('/');
}

function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `<li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(
        page.title
      )}</a>${date}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Index</title>
</head>
<body>
<h1>All Pages</h1>
<ul>
${items}
</ul>
</body>
</html>
`;
}

function resolvePluginModule(spec: string, context: PluginContext): Plugin | undefined {
  try {
    const resolved = require.resolve(spec, { paths: [process.cwd()] });
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const loaded = require(resolved);
    const exported = loaded && 'default' in loaded ? loaded.default : loaded;
    if (typeof exported === 'function') {
      const instance = new (exported as new (ctx: PluginContext) => Plugin)(context);
      return instance;
    }
    if (exported && typeof exported === 'object' && typeof exported.name === 'string') {
      return exported as Plugin;
    }
  } catch {
    // Ignore plugins that cannot be resolved or instantiated.
  }
  return undefined;
}

/**
 * Assemble the plugin pipeline: the built-in markdown and template plugins run
 * first, followed by any plugins declared in the project configuration.
 */
export function buildPlugins(context: PluginContext): Plugin[] {
  const plugins: Plugin[] = [new MarkdownPlugin(), new TemplatePlugin(context)];

  const config = loadConfig(process.cwd());
  for (const spec of config.plugins ?? []) {
    const plugin = resolvePluginModule(spec, context);
    if (plugin) {
      plugins.push(plugin);
    }
  }

  return plugins;
}

export function createEngine(options: BuildOptions): {
  context: PluginContext;
  pipeline: PluginPipeline;
} {
  const contentDir = path.resolve(options.contentDir ?? DEFAULT_CONTENT_DIR);
  const outputDir = path.resolve(options.outputDir ?? DEFAULT_OUTPUT_DIR);
  const templatesDir = options.templatesDir ?? DEFAULT_TEMPLATES_DIR;

  const context: PluginContext = {
    options,
    contentDir,
    outputDir,
    templatesDir,
    pages: [],
  };

  const pipeline = new PluginPipeline(buildPlugins(context));

  return { context, pipeline };
}

/**
 * Build the static site: read markdown from contentDir and write HTML files
 * (one per page plus an index.html) into outputDir. The core engine only
 * orchestrates the plugin pipeline; parsing and rendering are delegated to the
 * built-in MarkdownPlugin and TemplatePlugin.
 */
export function buildSite(options: BuildOptions): Site {
  const { context, pipeline } = createEngine(options);

  pipeline.runSync('onStart');
  pipeline.runSync('beforeBuild');

  const files = listMarkdownFiles(context.contentDir).sort();

  const pages: Page[] = files.map((file) => {
    const page: Page = {
      slug: deriveSlug(file, context.contentDir),
      title: '',
      date: undefined,
      tags: [],
      html: '',
      sourcePath: file,
      frontmatter: {},
      template: undefined,
      layout: undefined,
    };
    pipeline.runFileSync(page);
    return page;
  });

  pages.sort((a, b) => {
    if (a.date && b.date) {
      return b.date.localeCompare(a.date);
    }
    if (a.date) return -1;
    if (b.date) return 1;
    return a.title.localeCompare(b.title);
  });

  context.pages = pages;

  fs.mkdirSync(context.outputDir, { recursive: true });

  pipeline.runSync('afterBuild');

  fs.writeFileSync(path.join(context.outputDir, 'index.html'), renderIndex(pages));

  pipeline.runSync('onEnd');

  return { pages, outputDir: context.outputDir };
}

export { Frontmatter, Page, BuildOptions, Site } from './types';
export { splitFrontmatter, parseMarkdown, escapeHtml } from './markdown';
export { buildSite } from './engine';

import { buildSite } from './index';
import {
  DevServerPlugin,
  RELOAD_MESSAGE,
  LIVE_RELOAD_SCRIPT,
  injectLiveReloadScript,
} from './plugins/dev-server-plugin';

export { RELOAD_MESSAGE, LIVE_RELOAD_SCRIPT, injectLiveReloadScript };
export type { DevServer, ServeOptions } from './types';

/**
 * Start a live-reload development server.
 *
 * Performs an initial build, serves the generated site from outputDir over
 * HTTP, injects a WebSocket client script into HTML responses, watches the
 * content and templates directories for changes, rebuilds on change, and tells
 * connected browsers to reload when a rebuild completes.
 */
export async function startDevServer(options: import('./types').ServeOptions = {}): Promise<import('./types').DevServer> {
  const plugin = new DevServerPlugin(buildSite, options);
  return plugin.start();
}

